SELECT gptg.gene AS hugoGeneSymbol, gptg.gene_panel_id AS genePanelId FROM gene_panel_to_gene_derived gptg WHERE gptg.gene_panel_id IN ( SELECT DISTINCT stgp.gene_panel_id FROM sample_to_gene_panel_derived stgp
stgp.alteration_type = #{alterationType} AND
) GROUP BY gptg.gene, gptg.gene_panel_id ORDER BY gptg.gene, gptg.gene_panel_id

