#{entityId}
AND sgp.genetic_profile_id IN
#{profileId}
ORDER BY entityUniqueId, geneticProfileId

SELECT DISTINCT sd.patient_unique_id AS entityUniqueId, sgp.gene_panel_id AS genePanelId, sgp.genetic_profile_id AS geneticProfileId FROM sample_to_gene_panel_derived sgp INNER JOIN sample_derived sd ON sgp.sample_unique_id = sd.sample_unique_id WHERE sd.patient_unique_id IN
#{entityId}
AND sgp.genetic_profile_id IN
#{profileId}
ORDER BY entityUniqueId, geneticProfileId

